from collections import deque

def solve(grid):
    if not grid:
        return []
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    best = None  # (count_of_2, area, min_r, max_r, min_c, max_c)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                queue = deque()
                queue.append((r, c))
                visited[r][c] = True
                min_r = max_r = r
                min_c = max_c = c
                count2 = 0
                cell_count = 0
                while queue:
                    cr, cc = queue.popleft()
                    cell_count += 1
                    if grid[cr][cc] == 2:
                        count2 += 1
                    if cr < min_r:
                        min_r = cr
                    if cr > max_r:
                        max_r = cr
                    if cc < min_c:
                        min_c = cc
                    if cc > max_c:
                        max_c = cc
                    # explore 4-directional neighbors
                    nr = cr - 1
                    if nr >= 0 and not visited[nr][cc] and grid[nr][cc] != 0:
                        visited[nr][cc] = True
                        queue.append((nr, cc))
                    nr = cr + 1
                    if nr < rows and not visited[nr][cc] and grid[nr][cc] != 0:
                        visited[nr][cc] = True
                        queue.append((nr, cc))
                    nc = cc - 1
                    if nc >= 0 and not visited[cr][nc] and grid[cr][nc] != 0:
                        visited[cr][nc] = True
                        queue.append((cr, nc))
                    nc = cc + 1
                    if nc < cols and not visited[cr][nc] and grid[cr][nc] != 0:
                        visited[cr][nc] = True
                        queue.append((cr, nc))
                # select component with most 2's; tie-break by larger area
                if best is None or count2 > best[0] or (count2 == best[0] and cell_count > best[1]):
                    best = (count2, cell_count, min_r, max_r, min_c, max_c)

    if best is None:
        return []
    _, _, min_r, max_r, min_c, max_c = best
    return [row[min_c:max_c+1] for row in grid[min_r:max_r+1]]
